<script setup>defineProps({ model: { type: Object, required: true } });</script>
<template><article class="panel garden-panel"><div class="panel-heading"><div><p class="eyebrow">Garden snapshot</p><h3>Today’s tomato patch</h3></div><span class="badge">Daily target: {{ model.dailyTarget }}</span></div><p class="panel-explainer">Each completed focus session grows today’s garden.</p><div class="daily-progress" :aria-label="`${model.dailyProgress} of ${model.dailyTarget} focus sessions completed today`"><span :style="{ width: `${(model.dailyProgress / model.dailyTarget) * 100}%` }"></span></div><p class="progress-copy">{{ model.dailyProgress }} of {{ model.dailyTarget }} focus sessions completed today</p><div class="garden-stage"><span aria-hidden="true">{{ model.gardenStage.emoji }}</span><div><strong>{{ model.gardenStage.title }}</strong><p>{{ model.gardenStage.copy }}</p></div></div><div class="week-history" aria-label="Focus sessions over the last seven days"><h4>Last 7 days</h4><ol><li v-for="day in model.recentDailyHistory" :key="day.date"><span class="week-bar" :style="{ height: `${Math.max(8, Math.min(100, (day.count / model.dailyTarget) * 100))}%` }" :title="`${day.date}: ${day.count} focus sessions`"></span><strong>{{ day.count }}</strong><small>{{ day.label }}</small></li></ol></div><div v-if="model.sessionHistory.length" class="history-list"><h4>Today’s harvests</h4><div v-for="item in model.sessionHistory" :key="item.completedAt" class="history-item"><span>{{ item.task }}</span><small>{{ item.minutes }} min</small></div></div></article></template>
